import styled from 'styled-components';

import type { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

export type GuitarRecording = Pick<
  ReturnType<typeof useGuitarInput>,
  'hasTake' | 'download' | 'downloadWithEffects' | 'exporting' | 'exportError'
>;

export const GuitarRecordingExport = ({
  recording,
}: {
  recording: GuitarRecording;
}) => {
  if (!recording.hasTake) return null;
  return (
    <Controls aria-label="Экспорт записанного аудио">
      <strong>Аудиозапись гитары / микрофона</strong>
      <Hint>
        Последний завершённый аудиодубль. Чистый WAV сохраняет исходный звук,
        WAV с эффектами использует текущие эффекты входа, громкость и
        шумоподавление. Правки нот не меняют аудиозапись.
      </Hint>
      <Actions>
        <button type="button" onClick={recording.download}>
          Скачать чистый WAV
        </button>
        <button
          type="button"
          disabled={recording.exporting}
          onClick={recording.downloadWithEffects}
        >
          {recording.exporting
            ? 'Обработка эффектов…'
            : 'Скачать WAV с эффектами'}
        </button>
      </Actions>
      {recording.exporting && (
        <Hint role="status">Готовим WAV с текущими эффектами…</Hint>
      )}
      {recording.exportError && (
        <Hint role="alert">{recording.exportError}</Hint>
      )}
    </Controls>
  );
};

const Controls = styled.section`
  display: grid;
  gap: 8px;
  min-width: 0;
  width: 100%;
  font-size: 12px;
`;

const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
`;

const Hint = styled.div`
  color: ${p => p.theme.textSecondary};
  line-height: 1.5;
`;
