import { useMemo } from 'react';
import { useSelector } from 'react-redux';

import { getNoteDuration } from 'app/services/MelodiesService';
import { Melody } from 'app/services/MelodiesService/types';
import { Note, selectSoundingNotes } from 'app/services/NotesService';
import {
  Session,
  getNextVisualTargets,
} from 'app/services/PlayAlongService/game';
import { getKeyboardLayout } from 'app/services/PlayAlongService/keyboardLayout';
import {
  getKeyboardLookAhead,
  getKeyboardNoteMotion,
} from 'app/services/PlayAlongService/keyboardMotion';
import { selectSettings } from 'app/services/SettingsService';

import { KeyHitFeedback, useHitCounts } from './KeyHitFeedback';
import { NoteTail } from './NoteTail';
import {
  Board,
  CueKey,
  Cues,
  ExtraLabel,
  FallingKey,
  Frame,
  Key,
  Row,
  Scroll,
  Sky,
} from './keyboardScene';
import { useKeyboardGeometry } from './useKeyboardGeometry';
import { useScreenNoteInput } from './useScreenNoteInput';

export const KeyboardRoll = ({
  melody,
  elapsed,
  speed,
  session,
  listening,
  playing,
  expectedNotes = [],
  children,
}: {
  melody: Melody;
  elapsed: number;
  speed: number;
  session: Session;
  listening: boolean;
  playing: boolean;
  expectedNotes?: Note[];
  children?: React.ReactNode;
}) => {
  const settings = useSelector(selectSettings);
  const sounding = useSelector(selectSoundingNotes);
  const hitCounts = useHitCounts(melody.notes, session.results);
  const inputProps = useScreenNoteInput();
  const { rows } = useMemo(
    () => getKeyboardLayout(melody.notes, settings),
    [melody.notes, settings],
  );
  const geometry = useKeyboardGeometry(rows);
  const targets = rows.flatMap(row => row.targets);
  // Queue every keycap before its bottom edge enters the clipped scene.
  const horizon = getKeyboardLookAhead(
    speed,
    geometry.distance,
    Math.max(
      0,
      ...Object.values(geometry.keys).map(box => box.top + box.height),
    ),
  );
  const nextTargets = getNextVisualTargets(
    session,
    melody.notes,
    elapsed,
    listening,
  );
  const visible = melody.notes
    .map((note, index) => ({ ...note, index }))
    .filter(
      note =>
        note.start < elapsed + horizon &&
        note.start + getNoteDuration(note) > elapsed - 250 * speed,
    );
  const guide = listening
    ? melody.notes
        .filter(
          note =>
            note.start <= elapsed &&
            note.start + getNoteDuration(note) > elapsed,
        )
        .map(({ note }) => note)
    : [];

  return (
    <Scroll tabIndex={0} aria-label="Подсказки и компьютерная клавиатура">
      <Frame
        ref={geometry.frame}
        $rows={rows.length}
        data-testid="keyboard-roll"
      >
        <Sky>{children}</Sky>
        <Board ref={geometry.board} aria-label="Компьютерная клавиатура">
          {rows.map(row => (
            <Row
              key={row.id}
              $extra={row.id === 'unmapped'}
              aria-label={row.label}
            >
              {row.id === 'unmapped' && (
                <ExtraLabel>Ноты вне раскладки</ExtraLabel>
              )}
              {row.targets.map(target => (
                <Key
                  key={target.id}
                  type="button"
                  data-key-id={target.id}
                  disabled={!target.note}
                  $color={target.color}
                  $expected={
                    !!target.note && expectedNotes.includes(target.note)
                  }
                  $active={
                    !!target.note &&
                    (sounding.includes(target.note) ||
                      guide.includes(target.note))
                  }
                  aria-label={
                    target.note
                      ? `Клавиша ${target.label}, нота ${target.note}`
                      : `Клавиша ${target.label}, не назначена`
                  }
                  aria-pressed={
                    !!target.note &&
                    (sounding.includes(target.note) ||
                      guide.includes(target.note))
                  }
                  data-expected={
                    !!target.note && expectedNotes.includes(target.note)
                  }
                  style={{
                    left: `${target.left}%`,
                    width: `calc(${target.width}% - 3px)`,
                  }}
                  {...(target.note ? inputProps(target.note, target.id) : {})}
                >
                  <kbd>{target.label}</kbd>
                  {target.note && <small>{target.note}</small>}
                  <KeyHitFeedback
                    key={target.note}
                    hits={target.note ? hitCounts.get(target.note) || 0 : 0}
                    enabled={playing && !listening}
                    color={target.color}
                  />
                </Key>
              ))}
            </Row>
          ))}
        </Board>
        <Cues aria-label="Следующие клавиши">
          {visible.map(note => {
            const next = nextTargets.includes(note.index);
            const result = session.results[note.index];
            const played = result === 'perfect' || result === 'good';
            const target = targets.find(target => target.note === note.note)!;
            const box = geometry.keys[target.id];
            if (!box) return null;
            const motion = getKeyboardNoteMotion(
              note,
              elapsed,
              speed,
              box.top,
              geometry.distance,
            );
            return (
              <FallingKey
                key={note.index}
                data-testid={`keyboard-note-${note.index}`}
                data-key-target={target.id}
                data-next={next}
                $next={next}
                style={{
                  left: box.left,
                  width: box.width,
                  height: box.height,
                  transform: `translate3d(0, ${motion.top}px, 0)`,
                }}
              >
                <NoteTail
                  note={note.note}
                  height={motion.tailHeight}
                  color={target.color}
                  running={
                    playing &&
                    elapsed >= 0 &&
                    !listening &&
                    played &&
                    motion.sustaining &&
                    sounding.includes(note.note)
                  }
                  testId={`keyboard-tail-${note.index}`}
                />
                <CueKey
                  $color={target.color}
                  $expected={next}
                  $active={
                    next ||
                    (motion.sustaining &&
                      (sounding.includes(note.note) ||
                        guide.includes(note.note)))
                  }
                >
                  <kbd>{target.label}</kbd>
                  <small>{note.note}</small>
                </CueKey>
              </FallingKey>
            );
          })}
        </Cues>
      </Frame>
    </Scroll>
  );
};
