export class AudioInputTimeoutError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'AudioInputTimeoutError';
    Object.setPrototypeOf(this, AudioInputTimeoutError.prototype);
  }
}

// Browser permission and audio promises can remain pending indefinitely.
export const waitForAudioInput = <T>(
  pending: Promise<T>,
  signal: AbortSignal | undefined,
  message: string,
  timeoutMs = 10000,
): Promise<T> =>
  new Promise((resolve, reject) => {
    const clear = () => {
      clearTimeout(timer);
      signal?.removeEventListener('abort', abort);
    };
    const abort = () => {
      clear();
      reject(new DOMException('Audio input cancelled', 'AbortError'));
    };
    const timer = setTimeout(() => {
      clear();
      reject(new AudioInputTimeoutError(message));
    }, timeoutMs);
    signal?.addEventListener('abort', abort, { once: true });
    // Always observe late rejection, even after cancellation or timeout.
    pending.then(
      value => {
        clear();
        resolve(value);
      },
      error => {
        clear();
        reject(error);
      },
    );
    if (signal?.aborted) abort();
  });

