import { AiConnection, requestAi } from './aiProviders';
import { EffectPreset } from './presets';
import {
  EffectStage,
  defaultEffects,
  effectDefinitions,
  effectNames,
  normalizeEffects,
  toEffectStage,
} from './settings';

export const AI_PROMPT_LIMIT = 1000;

const invalidResult = () =>
  new Error('ИИ вернул неподходящие настройки. Попробуйте уточнить запрос.');

// Reject malformed model output before normalizing it into playable settings.
export const parseAiEffectPreset = (value: unknown): EffectPreset => {
  const result = value as {
    name?: unknown;
    description?: unknown;
    stages?: unknown;
  } | null;
  if (
    !result ||
    typeof result.name !== 'string' ||
    !result.name.trim() ||
    result.name.length > 60 ||
    typeof result.description !== 'string' ||
    !result.description.trim() ||
    result.description.length > 600 ||
    !Array.isArray(result.stages) ||
    result.stages.length < 1 ||
    result.stages.length > 4
  )
    throw invalidResult();

  const stages: EffectStage[] = result.stages.map(stage => {
    if (!stage || typeof stage !== 'object' || Array.isArray(stage))
      throw invalidResult();
    effectNames.forEach(name => {
      const effect = stage[name];
      if (
        !effect ||
        typeof effect !== 'object' ||
        typeof effect.enabled !== 'boolean' ||
        effectDefinitions[name].controls.some(
          ({ key, min, max }) =>
            typeof effect[key] !== 'number' ||
            !Number.isFinite(effect[key]) ||
            effect[key] < min ||
            effect[key] > max,
        )
      )
        throw invalidResult();
    });
    return toEffectStage(normalizeEffects('', stage));
  });
  if (!stages.some(stage => effectNames.some(name => stage[name].enabled)))
    throw invalidResult();

  const id = `custom-ai-${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 9)}`;
  return {
    id,
    name: result.name.trim(),
    description: result.description.trim(),
    settings: {
      ...defaultEffects(''),
      ...stages[0],
      pedals: stages.slice(1).map((stage, index) => ({
        id: `${id}-${index}`,
        presetId: `${id}-${index}`,
        name: `${result.name} · ${index + 2}`.slice(0, 60),
        enabled: true,
        stages: [stage],
      })),
    },
  };
};

export const generateAiEffect = async ({
  connection,
  prompt,
  signal,
}: {
  connection: AiConnection;
  prompt: string;
  signal: AbortSignal;
}): Promise<EffectPreset> => {
  const text = prompt.trim();
  if (!text || text.length > AI_PROMPT_LIMIT)
    throw new Error(`Опишите звук: от 1 до ${AI_PROMPT_LIMIT} символов.`);
  if (!connection.model.trim())
    throw new Error('Выберите или введите ID текстовой модели.');
  const schema = {
    type: 'object',
    additionalProperties: false,
    required: ['name', 'description', 'stages'],
    properties: {
      name: { type: 'string', maxLength: 60 },
      description: { type: 'string', maxLength: 600 },
      stages: {
        type: 'array',
        minItems: 1,
        maxItems: 4,
        items: {
          type: 'object',
          additionalProperties: false,
          required: effectNames,
          properties: Object.fromEntries(
            effectNames.map(name => [
              name,
              {
                type: 'object',
                additionalProperties: false,
                required: [
                  'enabled',
                  ...effectDefinitions[name].controls.map(
                    control => control.key,
                  ),
                ],
                properties: {
                  enabled: { type: 'boolean' },
                  ...Object.fromEntries(
                    effectDefinitions[name].controls.map(control => [
                      control.key,
                      {
                        type: 'number',
                        minimum: control.min,
                        maximum: control.max,
                      },
                    ]),
                  ),
                },
              },
            ]),
          ),
        },
      },
    },
  };
  const system = `Ты звукорежиссёр Qwertophone. Создай цепочку по описанию звука, настроению, жанру или песне. Ответ только JSON по схеме: ${JSON.stringify(
    schema,
  )}. Все поля обязательны. Название и описание по-русски. Используй только доступные эффекты, минимум один включён. Одна секция обрабатывает сигнал в порядке: компрессор, квакушка wah-wah, перегруз с фильтром кабинета, трёхполосный EQ, хорус, эхо, реверберация. Секции выполняются последовательно. У квакушки depth задаёт автокачание; depth=0 оставляет ручное положение frequency, rate задаёт скорость в Гц, resonance задаёт Q фильтра. Обычно достаточно одной секции. Не добавляй громкость, код, новые виды эффектов и неизвестные поля. Учитывай отрицания: мягкий блюз не требует сильного перегруза; грустное настроение передавай тёплым тоном и сдержанным пространством. Для песен предлагай приближение, не утверждай, что анализировал запись, воспроизвёл оригинал или знаешь точное оборудование. Не подменяй гитарную партию басовой; если референс неоднозначен, поясни выбранную интерпретацию в description. Объясни в description характер обработки и её ограничения. Пример структуры: ${JSON.stringify(
    {
      name: 'Тёплый блюз',
      description: 'Мягкое насыщение и небольшое пространство.',
      stages: [
        toEffectStage({
          ...defaultEffects(''),
          distortion: { enabled: true, drive: 18, tone: 2800 },
        }),
      ],
    },
  )}`;
  const result = (await requestAi(connection, 'chat/completions', signal, {
    model: connection.model.trim(),
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: text },
    ],
    ...(connection.provider === 'custom'
      ? {}
      : { response_format: { type: 'json_object' } }),
    ...(connection.provider === 'openai'
      ? { max_completion_tokens: 10000 }
      : { max_tokens: 6000 }),
    stream: false,
  })) as {
    choices?: { message?: { content?: unknown }; finish_reason?: string }[];
  };
  const choice = result?.choices?.[0];
  const content = choice?.message?.content;
  if (
    choice?.finish_reason !== 'stop' ||
    typeof content !== 'string' ||
    content.length > 20000
  )
    throw invalidResult();
  try {
    return parseAiEffectPreset(
      JSON.parse(
        content.replace(/^\s*```(?:json)?\s*\n?/, '').replace(/\s*```\s*$/, ''),
      ),
    );
  } catch {
    throw invalidResult();
  }
};
