import { useCallback, useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { selectEffects } from 'app/services/EffectsService/selectors';
import { defaultEffects } from 'app/services/EffectsService/settings';
import {
  effectsActions,
  useEffectsSlice,
} from 'app/services/EffectsService/slice';
import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';
import { selectSettings } from 'app/services/SettingsService';
import { resumeAudio } from 'app/services/SynthesizerService';

import { createDrumOutput } from './audio';
import { DrumTrack, saveDrumState } from './patterns';
import { createRandomDrumBeat } from './randomize';
import {
  CustomDrumSample,
  DrumSample,
  MAX_SAMPLE_BYTES,
  listCustomSamples,
  saveCustomSample,
} from './samples';
import { drumActions, selectDrumMachine, useDrumMachineSlice } from './slice';
import { DrumOutput, createDrumTransport } from './transport';

export const useDrumMachinePlayback = () => {
  useDrumMachineSlice();
  useEffectsSlice();
  const dispatch = useDispatch();
  const state = useSelector(selectDrumMachine);
  const { bpm, timeSignature } = useSelector(selectSettings);
  const { instruments } = useSelector(selectEffects);
  const steps = getBeatsPerMeasure(timeSignature) * 4;
  const current = useRef({ ...state, bpm, steps });
  current.current = { ...state, bpm, steps };
  const [playing, setPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(-1);
  const [error, setError] = useState('');
  const [customSamples, setCustomSamples] = useState<CustomDrumSample[]>([]);
  const [importing, setImporting] = useState(false);
  const output = useRef<DrumOutput>();
  const sampleRequests = useRef(new Map<DrumTrack, number>());
  const pending = useRef<Promise<DrumOutput>>();
  const transport = useRef<ReturnType<typeof createDrumTransport>>();
  const lifecycle = useRef({ generation: 0, mounted: true }).current;

  useEffect(() => saveDrumState(state), [state]);
  useEffect(() => {
    let mounted = true;
    listCustomSamples().then(
      samples => {
        if (mounted && samples.length) {
          setCustomSamples(previous =>
            Array.from(
              new Map(
                [...samples, ...previous].map(sample => [sample.id, sample]),
              ).values(),
            ),
          );
        }
      },
      () => {}, // Built-in samples remain usable without IndexedDB.
    );
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    lifecycle.mounted = true;
    return () => {
      lifecycle.mounted = false;
      lifecycle.generation++;
      transport.current?.stop();
      output.current?.dispose();
      output.current = undefined;
      pending.current = undefined;
    };
  }, [lifecycle]);

  const getOutput = async () => {
    if (output.current) return output.current;
    if (!pending.current) {
      pending.current = createDrumOutput()
        .then(kit => {
          if (!lifecycle.mounted) {
            kit.dispose();
            throw new Error('Drum machine unmounted');
          }
          output.current = kit;
          return kit;
        })
        .finally(() => {
          pending.current = undefined;
        });
    }
    return pending.current;
  };

  const stop = useCallback(() => {
    lifecycle.generation++;
    transport.current?.stop();
    output.current?.stop();
    setPlaying(false);
    setLoading(false);
    setStep(-1);
  }, [lifecycle]);

  const toggle = async () => {
    if (playing || loading) {
      stop();
      return;
    }
    const request = ++lifecycle.generation;
    setLoading(true);
    setError('');
    try {
      const [, kit] = await Promise.all([resumeAudio(), getOutput()]);
      await Promise.all(
        Object.values(current.current.samples).map(sample =>
          sample.kind !== 'builtin'
            ? kit.loadSample(sample)
            : Promise.resolve(),
        ),
      );
      if (!lifecycle.mounted || request !== lifecycle.generation) return;
      transport.current = createDrumTransport(
        kit,
        () => current.current,
        setStep,
      );
      transport.current.start();
      setPlaying(true);
    } catch (cause) {
      if (lifecycle.mounted && request === lifecycle.generation) {
        setError(
          cause instanceof Error
            ? `Не удалось загрузить ударные. ${cause.message}`
            : 'Не удалось загрузить ударные. Попробуйте запустить ещё раз.',
        );
      }
    } finally {
      if (lifecycle.mounted && request === lifecycle.generation)
        setLoading(false);
    }
  };

  const preview = async (track: DrumTrack) => {
    const request = lifecycle.generation;
    setError('');
    try {
      const [, kit] = await Promise.all([resumeAudio(), getOutput()]);
      const sample = current.current.samples[track];
      if (!sample) return;
      if (sample.kind !== 'builtin') await kit.loadSample(sample);
      if (!lifecycle.mounted || request !== lifecycle.generation) return;
      kit.update(current.current);
      kit.hit(track, kit.now() + 0.01, { preview: true });
    } catch (cause) {
      if (lifecycle.mounted && request === lifecycle.generation) {
        setError(
          cause instanceof Error
            ? `Не удалось загрузить ударные. ${cause.message}`
            : 'Не удалось загрузить ударные. Попробуйте ещё раз.',
        );
      }
    }
  };

  const selectSample = async (track: DrumTrack, sample: DrumSample) => {
    const request = (sampleRequests.current.get(track) ?? 0) + 1;
    const generation = lifecycle.generation;
    sampleRequests.current.set(track, request);
    setError('');
    try {
      const [, kit] = await Promise.all([resumeAudio(), getOutput()]);
      if (sample.kind !== 'builtin') {
        await kit.loadSample(sample);
      }
      if (
        lifecycle.mounted &&
        request === sampleRequests.current.get(track) &&
        current.current.tracks.includes(track)
      ) {
        dispatch(drumActions.setSample({ track, sample }));
        if (generation === lifecycle.generation) {
          kit.update({
            ...current.current,
            samples: { ...current.current.samples, [track]: sample },
          });
          kit.hit(track, kit.now() + 0.01, { preview: true });
        }
      }
    } catch (cause) {
      if (lifecycle.mounted && request === sampleRequests.current.get(track))
        setError(
          cause instanceof Error
            ? cause.message
            : 'Не удалось загрузить семпл.',
        );
    }
  };

  const removeTrack = (track: DrumTrack) => {
    sampleRequests.current.set(
      track,
      (sampleRequests.current.get(track) ?? 0) + 1,
    );
    dispatch(drumActions.removeTrack(track));
  };

  const randomize = () => {
    const generated = createRandomDrumBeat(state.tracks, timeSignature, bpm);
    const effects = instruments.drums ?? defaultEffects('drums');
    sampleRequests.current.forEach((request, track) => {
      sampleRequests.current.set(track, request + 1);
    });
    dispatch(
      drumActions.setGeneratedBeat({
        pattern: generated.pattern,
        samples: generated.samples,
      }),
    );
    dispatch(
      effectsActions.setInstrument({
        timbre: 'drums',
        settings: { ...generated.effects, volume: effects.volume },
      }),
    );
    return generated.description;
  };

  const importSample = async (track: DrumTrack, blob: Blob, name: string) => {
    setError('');
    setImporting(true);
    try {
      if (!blob.size || blob.size > MAX_SAMPLE_BYTES) {
        throw new Error('Выберите непустой аудиофайл размером до 10 МБ.');
      }
      const sample: CustomDrumSample = {
        kind: 'custom',
        id: `custom:${Date.now().toString(36)}-${Math.random()
          .toString(36)
          .slice(2)}`,
        name,
      };
      const kit = await getOutput();
      await kit.loadSample(sample, blob);
      if (!lifecycle.mounted) return;
      await saveCustomSample(sample, blob);
      if (!lifecycle.mounted) return;
      setCustomSamples(previous => [...previous, sample]);
      dispatch(drumActions.setSample({ track, sample }));
    } catch (cause) {
      if (lifecycle.mounted)
        setError(
          cause instanceof Error
            ? cause.message
            : 'Не удалось сохранить семпл.',
        );
    } finally {
      if (lifecycle.mounted) setImporting(false);
    }
  };

  useEffect(() => {
    output.current?.update(state);
  }, [state]);

  return {
    state,
    bpm,
    steps,
    playing,
    loading,
    step,
    error,
    toggle,
    preview,
    stop,
    customSamples,
    importing,
    importSample,
    selectSample,
    removeTrack,
    randomize,
  };
};
