import { NoteInMelody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { Note } from 'app/services/NotesService/types';

import { GuitarTake } from './capture';

type ModelNote = {
  startTimeSeconds: number;
  durationSeconds: number;
  pitchMidi: number;
};

export const convertDetectedNotes = (
  notes: ModelNote[],
  duration: number,
): NoteInMelody[] =>
  notes
    .filter(
      note =>
        Number.isInteger(note.pitchMidi) &&
        note.pitchMidi >= 12 &&
        note.pitchMidi <= 119 &&
        Number.isFinite(note.startTimeSeconds) &&
        Number.isFinite(note.durationSeconds) &&
        note.durationSeconds > 0 &&
        note.startTimeSeconds * 1000 < duration &&
        (note.startTimeSeconds + note.durationSeconds) * 1000 > 0,
    )
    .map(note => {
      const start = Math.max(0, Math.round(note.startTimeSeconds * 1000));
      const end = Math.min(
        duration,
        Math.round((note.startTimeSeconds + note.durationSeconds) * 1000),
      );
      return {
        note: `${chromaticNotes[note.pitchMidi % 12]}${
          Math.floor(note.pitchMidi / 12) - 1
        }` as Note,
        start,
        duration: end - start,
      };
    })
    .filter(note => note.duration > 0)
    .sort((a, b) => a.start - b.start || a.note.localeCompare(b.note));

let engine:
  | Promise<{
      model: import('@spotify/basic-pitch').BasicPitch;
      api: typeof import('@spotify/basic-pitch');
      tf: typeof import('@tensorflow/tfjs');
    }>
  | undefined;
let queue: Promise<unknown> = Promise.resolve();

const getEngine = () => {
  if (!engine) {
    engine = Promise.all([
      import('@spotify/basic-pitch'),
      import('@tensorflow/tfjs'),
    ])
      .then(async ([api, tf]) => {
        await tf.ready();
        const model = new api.BasicPitch(
          `${process.env.PUBLIC_URL}/models/basic-pitch/model.json`,
        );
        await model.model;
        return { model, api, tf };
      })
      .catch(error => {
        engine = undefined;
        throw error;
      });
  }
  return engine;
};

export const transcribeGuitar = (
  take: GuitarTake,
  onProgress: (progress: number) => void,
  signal: AbortSignal,
): Promise<NoteInMelody[]> => {
  const run = async () => {
    const checkCancelled = () => {
      if (signal.aborted) throw new DOMException('Cancelled', 'AbortError');
    };
    checkCancelled();
    if (take.samples.length < take.sampleRate * 0.06) return [];
    const { model, api, tf } = await getEngine();
    checkCancelled();
    onProgress(0.05);
    const offline = new OfflineAudioContext(
      1,
      Math.ceil((take.samples.length * 22050) / take.sampleRate),
      22050,
    );
    const buffer = offline.createBuffer(
      1,
      take.samples.length,
      take.sampleRate,
    );
    buffer.copyToChannel(take.samples, 0);
    const source = offline.createBufferSource();
    source.buffer = buffer;
    source.connect(offline.destination);
    source.start();
    const resampled = await offline.startRendering();
    checkCancelled();
    const frames: number[][] = [];
    const onsets: number[][] = [];
    // Basic Pitch 1.0.1 leaves intermediate tensors to its caller. Serialise
    // inferences and scope them so each take releases tensors after decoding.
    tf.engine().startScope();
    try {
      await model.evaluateModel(
        resampled,
        (nextFrames, nextOnsets) => {
          checkCancelled();
          frames.push(...nextFrames);
          onsets.push(...nextOnsets);
        },
        value => {
          checkCancelled();
          onProgress(0.05 + value * 0.9);
        },
      );
      checkCancelled();
      const notes = api.noteFramesToTime(
        api.outputToNotesPoly(frames, onsets, 0.35, 0.3, 5, true, 1600, 50),
      );
      onProgress(1);
      return convertDetectedNotes(
        notes,
        Math.round((take.samples.length / take.sampleRate) * 1000),
      );
    } finally {
      tf.engine().endScope();
    }
  };
  const result = queue.then(run, run);
  queue = result.catch(() => {});
  return result;
};
