import { useEffect, useState } from 'react';
import styled from 'styled-components';

import {
  Chord,
  KeyMode,
  chordSymbol,
  chordTones,
  chordVoicing,
  formatPitch,
  pitchClass,
} from 'app/services/ChordsService';
import {
  BorrowingGroup,
  borrowedChords,
  chordMoves,
  connectedVoicings,
  foreignTones,
  melodyRelation,
  primaryDominant,
  sharedTones,
  voicingSettings,
} from 'app/services/ChordsService/harmony';
import {
  CHORD_SERIES_URL,
  HarmonyLessonId,
  harmonyLessons,
  lessonExamples,
  lessonSource,
} from 'app/services/ChordsService/lessons';
import { ChordPlayback } from 'app/services/ChordsService/useChordPreview';
import { Note } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';

type ExplorerMode = BorrowingGroup | 'steps';
const modes: { value: ExplorerMode; label: string }[] = [
  { value: 'neighbors', label: 'Соседи на круге' },
  { value: 'parallel', label: 'Одноимённый лад' },
  { value: 'secondary', label: 'Побочные доминанты' },
  { value: 'steps', label: 'Шаги между аккордами' },
];

export const HarmonyExplorer = ({
  tonic,
  mode,
  chord,
  octave,
  inversion,
  bpm,
  unpitched,
  playback,
  onSelect,
}: {
  tonic: string;
  mode: KeyMode;
  chord: Chord;
  octave: number;
  inversion: number;
  bpm: number;
  unpitched: boolean;
  playback: ChordPlayback;
  onSelect: (chord: Chord, inversion?: number, octave?: number) => void;
}) => {
  const [lessonId, setLessonId] = useState<HarmonyLessonId>('orientation');
  const [explorerMode, setExplorerMode] = useState<ExplorerMode>('neighbors');
  const [smooth, setSmooth] = useState(true);
  const [exampleOctave, setExampleOctave] = useState(4);
  const [playingExample, setPlayingExample] = useState<string | null>(null);
  const [melody, setMelody] = useState('G');
  const [route, setRoute] = useState<Chord[]>([{ root: tonic, quality: mode }]);
  const lesson = harmonyLessons.find(item => item.id === lessonId)!;
  const examples = lessonExamples(lessonId, tonic, mode);
  const last = route[route.length - 1];
  const suggestions =
    explorerMode === 'steps'
      ? chordMoves(last)
      : explorerMode === 'secondary'
      ? [
          primaryDominant(tonic, mode),
          ...borrowedChords(tonic, mode, explorerMode),
        ]
      : borrowedChords(tonic, mode, explorerMode);
  const outside = foreignTones(chord, tonic, mode);
  const relation = melodyRelation(chord, melody, tonic, mode);
  const { stop } = playback;
  const currentOption = suggestions.find(
    option =>
      pitchClass(option.chord.root) === pitchClass(chord.root) &&
      option.chord.quality === chord.quality,
  );

  useEffect(() => {
    stop();
  }, [tonic, mode, bpm, smooth, exampleOctave, stop]);
  useEffect(() => {
    setRoute([{ root: tonic, quality: mode }]);
  }, [tonic, mode]);

  const choose = (next: Chord, inversion = 0, register = octave) => {
    stop();
    onSelect(next, inversion, register);
  };
  const listen = (id: string, chords: Chord[]) => {
    if (
      playback.isPlaying &&
      playingExample === id &&
      playback.activeStep !== null
    ) {
      stop();
      return;
    }
    setPlayingExample(id);
    playback.playSequence(
      connectedVoicings(chords, exampleOctave, smooth),
      120000 / bpm,
    );
  };
  const isActive = (id: string) =>
    playback.isPlaying && playback.activeStep !== null && playingExample === id;
  const progression = (id: string, chords: Chord[]) => {
    const voiced = connectedVoicings(chords, exampleOctave, smooth);
    return (
      <Progression aria-label="Последовательность аккордов">
        {chords.map((item, index) => {
          const bass = voiced[index][0].slice(0, -1);
          return (
            <ChordButton
              key={index}
              type="button"
              aria-label={`Разобрать ${chordSymbol(item)}, шаг ${index + 1}`}
              aria-current={
                isActive(id) && playback.activeStep === index
                  ? 'step'
                  : undefined
              }
              onClick={() => {
                const setting = voicingSettings(item, voiced[index]);
                choose(item, setting.inversion, setting.octave);
              }}
            >
              <strong>
                {chordSymbol(item)}
                {pitchClass(bass) !== pitchClass(item.root) && (
                  <small>
                    /
                    {formatPitch(
                      chordTones(item).find(
                        tone => pitchClass(tone) === pitchClass(bass),
                      ) ?? bass,
                    )}
                  </small>
                )}
              </strong>
              <span>{index + 1}</span>
            </ChordButton>
          );
        })}
      </Progression>
    );
  };

  return (
    <Section id="harmony-explorer" aria-label="Учимся выбирать аккорды">
      <Header>
        <div>
          <Eyebrow>ОТ КАТАЛОГА К МУЗЫКЕ</Eyebrow>
          <h2>Как выбирать аккорды</h2>
        </div>
        <Source href={CHORD_SERIES_URL} target="_blank" rel="noreferrer">
          Серия «Какие аккорды можно?» · Нескучный Саунд ↗
        </Source>
      </Header>
      <Lead>
        Слушайте аккорд в окружении других: какие звуки он сохраняет, что меняет
        и куда ведёт. Выбирайте краску и направление для своей музыкальной
        фразы.
      </Lead>
      <LessonField>
        Тема гармонии
        <select
          value={lessonId}
          onChange={event => {
            stop();
            const id = event.target.value as HarmonyLessonId;
            setLessonId(id);
            setExplorerMode(
              id === 'parallel' || id === 'context'
                ? 'parallel'
                : id === 'secondary' || id === 'melody'
                ? 'secondary'
                : id === 'steps' || id === 'common'
                ? 'steps'
                : 'neighbors',
            );
          }}
        >
          {harmonyLessons.map(item => (
            <option key={item.id} value={item.id}>
              {item.title}
            </option>
          ))}
        </select>
      </LessonField>
      <LessonCard aria-label="Объяснение темы">
        <h3>{lesson.title}</h3>
        <p>{lesson.idea}</p>
        <p>{lesson.task}</p>
        <Source href={lessonSource(lesson)} target="_blank" rel="noreferrer">
          Разбор автора с {Math.floor(lesson.seconds / 60)}:
          {String(lesson.seconds % 60).padStart(2, '0')} ↗
        </Source>
      </LessonCard>
      <ListeningSettings>
        <label>
          <input
            type="checkbox"
            checked={smooth}
            onChange={event => setSmooth(event.target.checked)}
          />
          Сближать голоса обращениями
        </label>
        <label>
          Октава примеров
          <select
            value={exampleOctave}
            onChange={event => setExampleOctave(Number(event.target.value))}
          >
            {[2, 3, 4, 5].map(value => (
              <option key={value} value={value}>
                {value}
              </option>
            ))}
          </select>
        </label>
        <Muted>По две доли на аккорд · {bpm} BPM · текущий тембр</Muted>
      </ListeningSettings>
      <Examples aria-label="Сравнение гармонических ходов">
        {examples.map((example, index) => {
          const id = `${lessonId}-${index}`;
          return (
            <Example key={id} aria-label={example.title}>
              <h4>{example.title}</h4>
              <Muted>Контекст: {chordSymbol(example.context)}</Muted>
              {progression(id, example.chords)}
              {lessonId === 'common' && (
                <p>
                  Общие звуки соседних звеньев:{' '}
                  {example.chords
                    .slice(1)
                    .map((next, position) => {
                      const common = sharedTones(
                        example.chords[position],
                        next,
                      );
                      return `${chordSymbol(
                        example.chords[position],
                      )} → ${chordSymbol(next)}: ${
                        common.length
                          ? common.map(formatPitch).join(', ')
                          : 'нет'
                      }`;
                    })
                    .join('; ')}
                  .
                </p>
              )}
              <Action
                type="button"
                disabled={unpitched}
                aria-pressed={isActive(id)}
                onClick={() => listen(id, example.chords)}
              >
                {isActive(id)
                  ? `Остановить: ${example.title}`
                  : `Слушать: ${example.title}`}
              </Action>
            </Example>
          );
        })}
      </Examples>
      <Muted>
        Пояснения используют C и Am. Примеры перенесены относительно выбранной
        на круге тональности. Нажмите на звено, чтобы разобрать его в карточке.
      </Muted>

      <Subsection aria-label="Гармонический навигатор">
        <h3>Попробуйте другой ход</h3>
        <ModeList role="group" aria-label="Способ выбора аккордов">
          {modes.map(item => (
            <ModeButton
              key={item.value}
              type="button"
              aria-pressed={explorerMode === item.value}
              onClick={() => {
                stop();
                setExplorerMode(item.value);
              }}
            >
              {item.label}
            </ModeButton>
          ))}
        </ModeList>
        <Muted>
          {explorerMode === 'steps'
            ? `Маршрут строится от последнего аккорда ${chordSymbol(
                last,
              )}. Тональность остаётся ориентиром на круге.`
            : `Тональный центр: ${chordSymbol({
                root: tonic,
                quality: mode,
              })}. Сравните варианты и проследите, какие ноты добавляются.`}
        </Muted>
        <Options>
          {suggestions.map((option, index) => {
            const common = sharedTones(
              explorerMode === 'steps' ? last : chord,
              option.chord,
            );
            return (
              <Option
                key={`${explorerMode}-${index}`}
                type="button"
                disabled={explorerMode === 'steps' && route.length >= 16}
                onClick={() => {
                  if (explorerMode === 'steps')
                    setRoute([...route, option.chord]);
                  choose(option.chord);
                }}
              >
                <span>{option.label}</span>
                <strong>
                  {chordSymbol(option.chord)}
                  {option.target && ` → ${chordSymbol(option.target)}`}
                </strong>
                <span>
                  Общие звуки:{' '}
                  {common.length ? common.map(formatPitch).join(' · ') : 'нет'}
                </span>
              </Option>
            );
          })}
        </Options>
        {explorerMode === 'steps' ? (
          <RouteBox aria-label="Мой аккордовый маршрут">
            <h4>Мой маршрут · {route.length}/16</h4>
            {progression('route', route)}
            <Actions>
              <Action
                type="button"
                disabled={unpitched || route.length < 2}
                onClick={() => listen('route', route)}
              >
                {isActive('route') ? 'Остановить маршрут' : 'Слушать маршрут'}
              </Action>
              <QuietAction
                type="button"
                disabled={route.length < 2}
                onClick={() => {
                  stop();
                  setRoute(route.slice(0, -1));
                }}
              >
                Убрать последний шаг
              </QuietAction>
              <QuietAction
                type="button"
                disabled={
                  chord.quality !== 'major' && chord.quality !== 'minor'
                }
                onClick={() => {
                  stop();
                  setRoute([chord]);
                }}
              >
                Начать с выбранного аккорда
              </QuietAction>
            </Actions>
            <Muted>
              Короткий повторяющийся рисунок проще услышать как фразу. Для
              нового начала выберите мажорное или минорное трезвучие.
            </Muted>
          </RouteBox>
        ) : (
          <ContextBox aria-label="Аккорд в тональности">
            <h4>
              {chordSymbol(chord)} в{' '}
              {chordSymbol({ root: tonic, quality: mode })}
            </h4>
            <p>
              {currentOption?.explanation ??
                'Сопоставьте состав выбранного аккорда со звукорядом тональности и послушайте его в короткой фразе.'}
            </p>
            <Muted>
              Ноты вне исходной гаммы:{' '}
              {outside.length
                ? outside.map(formatPitch).join(' · ')
                : 'все ноты входят в гамму'}
              .
            </Muted>
            {currentOption?.target && (
              <Action
                type="button"
                disabled={unpitched}
                aria-pressed={isActive('resolution')}
                onClick={() =>
                  listen('resolution', [
                    { root: tonic, quality: mode },
                    chord,
                    currentOption.target!,
                    { root: tonic, quality: mode },
                  ])
                }
              >
                {isActive('resolution')
                  ? 'Остановить разрешение'
                  : 'Слушать разрешение'}{' '}
                {chordSymbol(chord)} → {chordSymbol(currentOption.target)}
              </Action>
            )}
          </ContextBox>
        )}
      </Subsection>
      <Subsection aria-label="Мелодия над аккордом">
        <h3>Одна нота меняет впечатление</h3>
        <MelodyControls>
          <label>
            Нота мелодии
            <select
              value={melody}
              onChange={event => {
                stop();
                setMelody(event.target.value);
              }}
            >
              {chromaticNotes.map(note => (
                <option key={note} value={note}>
                  {formatPitch(note)}
                </option>
              ))}
            </select>
          </label>
          <Action
            type="button"
            disabled={unpitched}
            onClick={() => {
              setPlayingExample(null);
              const voiced = chordVoicing(chord, octave, inversion);
              const top = voiced[voiced.length - 1];
              const melodyOctave =
                Number(top.slice(-1)) +
                (pitchClass(melody) <= pitchClass(top) ? 1 : 0);
              playback.play([...voiced, `${melody}${melodyOctave}` as Note]);
            }}
          >
            Послушать аккорд с мелодией
          </Action>
        </MelodyControls>
        <p aria-label="Отношение мелодии к аккорду">
          {formatPitch(melody)}{' '}
          {relation.inChord
            ? `входит в ${chordSymbol(chord)}.`
            : relation.inScale
            ? 'входит в исходную гамму, но не в выбранный аккорд.'
            : 'находится вне исходной гаммы и выбранного аккорда.'}
          {relation.semitoneNeighbors.length > 0 &&
            ` Рядом на полутон: ${relation.semitoneNeighbors
              .map(formatPitch)
              .join(', ')}. Это возможный источник напряжения.`}
        </p>
        <Muted>
          Можно изменить ноту, гармонию, регистр или сохранить напряжение ради
          нужного характера. Общий звук часто помогает связать необычные
          аккорды; устойчивость зависит и от ритма, и от мелодии.
        </Muted>
      </Subsection>
      {unpitched && (
        <Muted>Для прослушивания выберите мелодический тембр в хедере.</Muted>
      )}
      <SourceDetails>
        <summary>Источники и адаптация</summary>
        <p>
          Это интерактивная адаптация идей серии. Примеры для сравнения
          составлены для приложения. Для выпусков 1 и 4–8 изучены русские
          автосубтитры; для выпусков 2 и 3 доступны авторские описания и
          таймкоды, а их основные идеи повторно разобраны в выпуске 4.
          Автосубтитры могут искажать обозначения нот; интервалы в приложении
          проверяются отдельно.
        </p>
      </SourceDetails>
    </Section>
  );
};

