import {
  InstrumentEffects,
  normalizeEffects,
} from 'app/services/EffectsService/settings';

export interface EffectsRack {
  input: GainNode;
  update: (settings: InstrumentEffects) => void;
  dispose: () => void;
}

// The impulse is shared across instruments in the same context.
const impulses = new WeakMap<BaseAudioContext, AudioBuffer>();
const reverbImpulse = (audio: BaseAudioContext) => {
  const cached = impulses.get(audio);
  if (cached) return cached;
  const length = Math.ceil(audio.sampleRate * 2);
  const buffer = audio.createBuffer(2, length, audio.sampleRate);
  let seed = 1;
  for (let channel = 0; channel < 2; channel++) {
    const data = buffer.getChannelData(channel);
    for (let i = 0; i < length; i++) {
      seed = (seed * 16807) % 2147483647;
      data[i] = (seed / 1073741824 - 1) * Math.pow(1 - i / length, 3);
    }
  }
  impulses.set(audio, buffer);
  return buffer;
};

const createSingleEffectsRack = (
  audio: BaseAudioContext,
  destination: AudioNode,
  settings: InstrumentEffects,
  options: { lowLatency?: boolean; settingsKey?: string } = {},
): EffectsRack => {
  const nodes: AudioNode[] = [];
  const track = <T extends AudioNode>(node: T): T => {
    nodes.push(node);
    return node;
  };
  const gain = (value = 1) => {
    const node = track(audio.createGain());
    node.gain.value = value;
    return node;
  };
  const filter = (type: BiquadFilterType, frequency: number) => {
    const node = track(audio.createBiquadFilter());
    node.type = type;
    node.frequency.value = frequency;
    node.Q.value = 0.7;
    return node;
  };
  const stage = () => {
    const input = gain();
    const output = gain();
    const dry = gain();
    const send = gain(0);
    const wet = gain(0);
    input.connect(dry).connect(output);
    input.connect(send);
    wet.connect(output);
    return { input, output, dry, send, wet };
  };

  const input = gain();
  const output = gain();
  const clean = gain();
  const processed = gain(0);
  input.connect(clean).connect(output);
  output.connect(destination);

  const compression = stage();
  const compressor = track(audio.createDynamicsCompressor());
  compressor.knee.value = 12;
  compressor.attack.value = 0.003;
  compressor.release.value = 0.25;
  compression.send.connect(compressor).connect(compression.wet);
  input.connect(compression.input);

  const wah = stage();
  const wahFilter = filter('bandpass', 900);
  const wahLfo = track(audio.createOscillator());
  const wahDepth = gain(0);
  wahLfo.connect(wahDepth).connect(wahFilter.detune);
  wah.send.connect(wahFilter).connect(wah.wet);
  compression.output.connect(wah.input);

  const distortion = stage();
  const highpass = filter('highpass', 80);
  const drive = gain();
  const shaper = track(audio.createWaveShaper());
  const curve = new Float32Array(4097);
  for (let i = 0; i < curve.length; i++) {
    curve[i] = Math.tanh(((i * 2) / (curve.length - 1) - 1) * 25);
  }
  shaper.curve = curve;
  shaper.oversample = options.lowLatency ? 'none' : '4x';
  const cabinet = filter('lowpass', 3500);
  distortion.send
    .connect(highpass)
    .connect(drive)
    .connect(shaper)
    .connect(cabinet)
    .connect(distortion.wet);
  wah.output.connect(distortion.input);

  const low = filter('lowshelf', 250);
  const mid = filter('peaking', 1000);
  const high = filter('highshelf', 4000);
  distortion.output.connect(low).connect(mid).connect(high);

  const chorus = stage();
  const chorusDelay = track(audio.createDelay(0.05));
  chorusDelay.delayTime.value = 0.02;
  const lfo = track(audio.createOscillator());
  const depth = gain(0);
  lfo.connect(depth).connect(chorusDelay.delayTime);
  chorus.send.connect(chorusDelay).connect(chorus.wet);
  high.connect(chorus.input);

  const echo = stage();
  const delay = track(audio.createDelay(1.1));
  const feedback = gain(0);
  const damping = filter('lowpass', 4500);
  echo.send.connect(delay).connect(echo.wet);
  delay.connect(damping).connect(feedback).connect(delay);
  chorus.output.connect(echo.input);

  const reverb = stage();
  const convolver = track(audio.createConvolver());
  convolver.buffer = reverbImpulse(audio);
  const reverbTone = filter('lowpass', 6000);
  reverb.send.connect(reverbTone).connect(convolver).connect(reverb.wet);
  echo.output.connect(reverb.input);
  reverb.output.connect(processed).connect(output);

  let initialized = false;
  const set = (param: AudioParam, value: number) => {
    if (!initialized) {
      param.value = value;
    } else {
      param.cancelScheduledValues(audio.currentTime);
      param.setTargetAtTime(
        value,
        audio.currentTime,
        options.lowLatency ? 0.003 : 0.015,
      );
    }
  };
  const mix = (
    node: ReturnType<typeof stage>,
    enabled: boolean,
    amount = 1,
  ) => {
    set(node.dry.gain, enabled ? 1 - amount : 1);
    set(node.send.gain, enabled ? 1 : 0);
    set(node.wet.gain, enabled ? amount : 0);
  };
  const update = (value: InstrumentEffects) => {
    const s = normalizeEffects(options.settingsKey ?? '', value);
    set(clean.gain, s.bypass ? 1 : 0);
    set(processed.gain, s.bypass ? 0 : 1);
    set(output.gain, s.volume / 100);
    mix(compression, s.compressor.enabled);
    set(compressor.threshold, s.compressor.threshold);
    set(compressor.ratio, s.compressor.ratio);
    mix(wah, s.wah.enabled);
    set(wahFilter.frequency, s.wah.frequency);
    set(wahFilter.Q, s.wah.resonance);
    set(wahLfo.frequency, s.wah.rate);
    // Sweep in cents so both halves cover the same musical interval. Limit
    // the excursion to keep the filter inside the pedal's 250–2500 Hz range.
    const wahRange =
      1200 * Math.log2(Math.min(s.wah.frequency / 250, 2500 / s.wah.frequency));
    set(
      wahDepth.gain,
      s.wah.enabled && !s.bypass ? (wahRange * s.wah.depth) / 100 : 0,
    );
    mix(distortion, s.distortion.enabled);
    set(drive.gain, (1 + s.distortion.drive * 0.3) / 25);
    set(cabinet.frequency, s.distortion.tone);
    set(low.gain, s.equalizer.enabled ? s.equalizer.low : 0);
    set(mid.gain, s.equalizer.enabled ? s.equalizer.mid : 0);
    set(high.gain, s.equalizer.enabled ? s.equalizer.high : 0);
    mix(chorus, s.chorus.enabled, s.chorus.mix / 100);
    set(lfo.frequency, s.chorus.rate);
    set(depth.gain, s.chorus.enabled ? s.chorus.depth / 1000 : 0);
    mix(echo, s.delay.enabled, s.delay.mix / 100);
    set(delay.delayTime, s.delay.time / 1000);
    set(
      feedback.gain,
      s.delay.enabled && !s.bypass ? s.delay.feedback / 100 : 0,
    );
    mix(reverb, s.reverb.enabled, s.reverb.mix / 100);
    set(reverbTone.frequency, s.reverb.tone);
    initialized = true;
  };
  update(settings);
  wahLfo.start();
  lfo.start();

  return {
    input,
    update,
    dispose: () => {
      wahLfo.stop();
      lfo.stop();
      nodes.forEach(node => node.disconnect());
    },
  };
};

// A source has one master level and bypass, regardless of the number of pedals.
// Keep pedal racks alive across parameter edits and footswitch presses so held
// notes continue through the same input and existing delay nodes.
export const createEffectsRack = (
  audio: BaseAudioContext,
  destination: AudioNode,
  settings: InstrumentEffects,
  options: { lowLatency?: boolean; settingsKey?: string } = {},
): EffectsRack => {
  const input = audio.createGain();
  const output = audio.createGain();
  const clean = audio.createGain();
  const processed = audio.createGain();
  const head = audio.createGain();
  input.connect(clean).connect(output);
  processed.connect(output).connect(destination);
  const manual = createSingleEffectsRack(
    audio,
    head,
    { ...settings, volume: 100 },
    options,
  );
  input.connect(manual.input);
  const pedals = new Map<string, { rack: EffectsRack; output: GainNode }>();
  let order = '';
  let initialized = false;
  let disposed = false;
  const set = (param: AudioParam, value: number) => {
    if (!initialized) param.value = value;
    else {
      param.cancelScheduledValues(audio.currentTime);
      param.setTargetAtTime(
        value,
        audio.currentTime,
        options.lowLatency ? 0.003 : 0.015,
      );
    }
  };
  const update = (value: InstrumentEffects) => {
    if (disposed) return;
    const next = normalizeEffects(options.settingsKey ?? '', value);
    manual.update({ ...next, volume: 100 });
    const steps = (next.pedals ?? []).flatMap(pedal =>
      pedal.stages.map((stage, index) => ({
        key: `${pedal.id}:${index}`,
        settings: {
          ...stage,
          volume: 100,
          bypass: next.bypass || !pedal.enabled,
        },
      })),
    );
    const nextOrder = JSON.stringify(steps.map(step => step.key));
    const keys = new Set(steps.map(step => step.key));
    pedals.forEach((pedal, key) => {
      if (keys.has(key)) return;
      pedal.rack.dispose();
      pedal.output.disconnect();
      pedals.delete(key);
    });
    steps.forEach(step => {
      const existing = pedals.get(step.key);
      if (existing) existing.rack.update(step.settings);
      else {
        const tail = audio.createGain();
        pedals.set(step.key, {
          output: tail,
          rack: createSingleEffectsRack(audio, tail, step.settings, {
            ...options,
            settingsKey: '',
          }),
        });
      }
    });
    if (order !== nextOrder) {
      head.disconnect();
      pedals.forEach(pedal => pedal.output.disconnect());
      let previous = head;
      steps.forEach(step => {
        const pedal = pedals.get(step.key)!;
        previous.connect(pedal.rack.input);
        previous = pedal.output;
      });
      previous.connect(processed);
      order = nextOrder;
    }
    set(clean.gain, next.bypass ? 1 : 0);
    set(processed.gain, next.bypass ? 0 : 1);
    set(output.gain, next.volume / 100);
    initialized = true;
  };
  update(settings);
  return {
    input,
    update,
    dispose: () => {
      if (disposed) return;
      disposed = true;
      manual.dispose();
      pedals.forEach(pedal => {
        pedal.rack.dispose();
        pedal.output.disconnect();
      });
      pedals.clear();
      [input, output, clean, processed, head].forEach(node =>
        node.disconnect(),
      );
    },
  };
};
