import { useEffect, useId, useRef, useState } from 'react';

import {
  AiConnection,
  AiPreferences,
  AiProviderId,
  aiBaseUrl,
  aiProviders,
  defaultAiConnection,
  loadAiModels,
  saveAiPreferences,
} from 'app/services/EffectsService/aiProviders';

export const AiConnectionSettings = ({
  preferences,
  onChange,
  disabled,
}: {
  preferences: AiPreferences;
  onChange: (value: AiPreferences) => void;
  disabled: boolean;
}) => {
  const connection =
    preferences.connections[preferences.provider] ??
    defaultAiConnection(preferences.provider);
  const [open, setOpen] = useState(!connection.apiKey);
  const [models, setModels] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const request = useRef<AbortController>();
  const id = useId();
  useEffect(
    () => () => {
      request.current?.abort();
      request.current = undefined;
    },
    [],
  );
  const update = (change: Partial<AiConnection>) => {
    onChange({
      ...preferences,
      connections: {
        ...preferences.connections,
        [connection.provider]: { ...connection, ...change },
      },
    });
    setMessage('');
    setError('');
  };

  return (
    <details open={open} onToggle={event => setOpen(event.currentTarget.open)}>
      <summary>
        Подключение ИИ ·{' '}
        {aiProviders.find(item => item.id === connection.provider)?.name}
      </summary>
      <fieldset disabled={disabled || loading}>
        <legend>Провайдер и модель</legend>
        <label>
          Провайдер ИИ
          <select
            value={connection.provider}
            onChange={event => {
              onChange({
                ...preferences,
                provider: event.target.value as AiProviderId,
              });
              setModels([]);
              setMessage('');
              setError('');
            }}
          >
            {aiProviders.map(provider => (
              <option key={provider.id} value={provider.id}>
                {provider.name}
              </option>
            ))}
          </select>
        </label>
        {connection.provider === 'custom' && (
          <label>
            Базовый адрес API
            <input
              type="url"
              value={connection.baseUrl}
              maxLength={500}
              placeholder="https://your-provider.example/v1"
              onChange={event => {
                update({ baseUrl: event.target.value });
                setModels([]);
              }}
            />
          </label>
        )}
        <label>
          API-ключ
          <input
            type="password"
            autoComplete="off"
            spellCheck={false}
            value={connection.apiKey}
            aria-describedby={`${id}-key-warning`}
            onChange={event => {
              update({ apiKey: event.target.value });
              setModels([]);
            }}
          />
        </label>
        <p id={`${id}-key-warning`}>
          Ключ будет храниться локально в этом браузере без шифрования после
          сохранения подключения. Он доступен скриптам страницы и пользователям
          этого профиля браузера. Запросы идут напрямую выбранному провайдеру;
          его API может быть платным. Аудио не отправляется.
        </p>
        <label>
          Модель ИИ
          <input
            value={connection.model}
            maxLength={200}
            list={`${id}-models`}
            placeholder="ID текстовой модели"
            onChange={event => update({ model: event.target.value })}
          />
          <datalist id={`${id}-models`}>
            {models.map(model => (
              <option key={model} value={model} />
            ))}
          </datalist>
        </label>
        <button
          type="button"
          onClick={async () => {
            setLoading(true);
            setError('');
            setMessage('');
            const controller = new AbortController();
            request.current = controller;
            const timeout = window.setTimeout(() => controller.abort(), 20000);
            controller.signal.addEventListener(
              'abort',
              () => window.clearTimeout(timeout),
              { once: true },
            );
            try {
              const next = await loadAiModels(connection, controller.signal);
              if (request.current !== controller) return;
              setModels(next);
              setMessage(
                next.length
                  ? `Доступно моделей: ${next.length}. Выберите модель в поле выше.`
                  : 'Текстовые модели не найдены. Введите ID вручную.',
              );
            } catch (reason) {
              if (request.current !== controller) return;
              setError(
                controller.signal.aborted
                  ? 'Список моделей не загрузился за 20 секунд. Введите ID вручную.'
                  : reason instanceof TypeError
                  ? 'Не удалось подключиться. Проверьте сеть и поддержку запросов из браузера (CORS) у провайдера.'
                  : reason instanceof Error
                  ? reason.message
                  : 'Не удалось загрузить модели.',
              );
            } finally {
              window.clearTimeout(timeout);
              if (request.current === controller) {
                request.current = undefined;
                setLoading(false);
              }
            }
          }}
        >
          {loading ? 'Загружаем модели…' : 'Загрузить модели'}
        </button>{' '}
        <button
          type="button"
          onClick={() => {
            setError('');
            try {
              aiBaseUrl(connection);
            } catch (reason) {
              setError((reason as Error).message);
              return;
            }
            const saved = saveAiPreferences({
              ...preferences,
              connections: {
                ...preferences.connections,
                [connection.provider]: connection,
              },
            });
            if (saved)
              setMessage('Подключение сохранено локально в этом браузере.');
            else {
              setMessage('');
              setError(
                'Браузер не разрешил сохранение. Ключ доступен только до закрытия панели.',
              );
            }
          }}
        >
          Сохранить подключение
        </button>{' '}
        <button
          type="button"
          disabled={!connection.apiKey}
          onClick={() => {
            const next = {
              ...preferences,
              connections: {
                ...preferences.connections,
                [connection.provider]: { ...connection, apiKey: '' },
              },
            };
            onChange(next);
            setModels([]);
            if (saveAiPreferences(next)) {
              setError('');
              setMessage('Ключ этого провайдера удалён из браузера.');
            } else {
              setMessage('');
              setError(
                'Не удалось удалить сохранённый ключ. Очистите данные сайта в настройках браузера.',
              );
            }
          }}
        >
          Удалить ключ
        </button>
        {connection.provider === 'openrouter' && (
          <p>
            Через OpenRouter можно выбрать Claude, GPT, Gemini, DeepSeek и
            другие текстовые модели.
          </p>
        )}
        <p>
          Можно загрузить актуальный список моделей или ввести ID вручную.
          Поддержка прямых запросов зависит от провайдера и его правил CORS.
        </p>
      </fieldset>
      {message && <p role="status">{message}</p>}
      {error && <p role="alert">{error}</p>}
    </details>
  );
};
