import { useCallback, useEffect, useRef, useState } from 'react';
import { batch, useSelector, useStore } from 'react-redux';

import {
  loadAudioRouting,
  saveAudioRouting,
} from 'app/services/AudioRoutingService/preferences';
import { selectEffects } from 'app/services/EffectsService/selectors';
import {
  InstrumentEffects,
  LIVE_INPUT_EFFECTS_KEY,
  defaultEffects,
  normalizeEffects,
} from 'app/services/EffectsService/settings';
import {
  effectsActions,
  useEffectsSlice,
} from 'app/services/EffectsService/slice';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { selectSettings, settingsActions } from 'app/services/SettingsService';
import { RootState } from 'app/services/types';

import { GuitarCapture, GuitarTake, openGuitarCapture } from './capture';
import {
  AudioInputTimeoutError,
  microphoneTimeoutMessage,
  waitForAudioInput,
} from './connection';
import { InputLatency } from './liveMonitor';
import {
  LiveTranscription,
  RecordingMode,
  createLiveTranscription,
} from './liveTranscription';
import {
  NoiseGateSettings,
  loadNoiseGate,
  normalizeNoiseGate,
  saveNoiseGate,
} from './noiseGateSettings';
import { createTimbreMonitor } from './timbreMonitor';
import { transcribeGuitar } from './transcribe';
import { downloadGuitarTake, downloadGuitarWav } from './wav';

const initialLiveEffects = defaultEffects(LIVE_INPUT_EFFECTS_KEY);

const builtInOutput = (devices: MediaDeviceInfo[]) =>
  devices.find(
    device =>
      device.kind === 'audiooutput' &&
      !!device.deviceId &&
      !['default', 'communications'].includes(device.deviceId) &&
      /built[ -]?in|internal|встроенн|macbook/i.test(device.label) &&
      /speaker|динамик|output|выход|audio|аудио/i.test(device.label) &&
      !/headphone|headset|наушник|гарнитур|hdmi|displayport|digital|цифров/i.test(
        device.label,
      ),
  );

const errorMessage = (error: unknown) => {
  if (error instanceof AudioInputTimeoutError) return error.message;
  const name = error instanceof Error ? error.name : '';
  if (name === 'NotAllowedError' || name === 'SecurityError')
    return 'Разрешите доступ к аудиовходу в настройках сайта и повторите подключение.';
  if (name === 'NotFoundError' || name === 'OverconstrainedError')
    return 'Аудиовход недоступен. Подключите аудиоинтерфейс и выберите его снова.';
  if (name === 'NotReadableError')
    return 'Не удалось открыть аудиовход. Проверьте подключение и другие аудиоприложения.';
  return 'Не удалось подключить аудиовход. Проверьте устройство и поддержку AudioWorklet в браузере.';
};

export const useGuitarInput = () => {
  const [savedRouting] = useState(loadAudioRouting);
  const [noiseGate, setNoiseGate] = useState(loadNoiseGate);
  const noiseGateRef = useRef(noiseGate);
  noiseGateRef.current = noiseGate;
  useEffectsSlice();
  const store = useStore<RootState>();
  const { isRecording, timbre } = useSelector(selectSettings);
  const [inputSound, setInputSound] = useState(savedRouting.inputSound);
  const [inputPolyphonic, setInputPolyphonic] = useState(
    savedRouting.inputPolyphonic,
  );
  const inputSoundRef = useRef(inputSound);
  const inputPolyphonicRef = useRef(inputPolyphonic);
  const timbreMonitor = useRef<ReturnType<typeof createTimbreMonitor>>();
  const instrumentEffects = useSelector(selectEffects).instruments[timbre];
  const liveEffects =
    useSelector(selectEffects).instruments[LIVE_INPUT_EFFECTS_KEY] ??
    initialLiveEffects;
  const effectsRef = useRef(liveEffects);
  effectsRef.current = liveEffects;
  const [monitoring, setMonitoring] = useState(false);
  const monitoringRef = useRef(false);
  const monitoringRequest = useRef(0);
  const pendingAnalysis = useRef<GuitarTake>();
  const [outputLevel, setOutputLevel] = useState({ rms: 0, peak: 0 });
  const [latency, setLatency] = useState<InputLatency>();
  const [connected, setConnected] = useState(false);
  const [connecting, setConnecting] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState('');
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [devicesReady, setDevicesReady] = useState(false);
  const [requestingDevices, setRequestingDevices] = useState(false);
  const [outputs, setOutputs] = useState<MediaDeviceInfo[]>([]);
  const [outputDeviceId, setOutputDeviceId] = useState(
    savedRouting.liveOutputDeviceId ?? '',
  );
  const [canSelectOutput, setCanSelectOutput] = useState(false);
  const [deviceId, setDeviceId] = useState(savedRouting.inputDeviceId);
  const [channel, setChannel] = useState(savedRouting.inputChannel);
  const [channels, setChannels] = useState(1);
  const [level, setLevel] = useState({ rms: 0, peak: 0 });
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [hasTake, setHasTake] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState('');
  const exportingRef = useRef(false);
  const [recordingMode, setRecordingMode] = useState<RecordingMode>('live');
  const [lastTakeIsLive, setLastTakeIsLive] = useState(false);
  const realtime = useRef<LiveTranscription>();
  const [drainRevision, setDrainRevision] = useState(0);
  const capture = useRef<GuitarCapture>();
  const taking = useRef<GuitarCapture>();
  const flushing = useRef<{
    input: GuitarCapture;
    close: boolean;
    recognition?: LiveTranscription;
  }>();
  const lastTake = useRef<GuitarTake>();
  const connectionRequest = useRef<AbortController>();
  const analysisRequest = useRef<AbortController>();
  const mounted = useRef(true);
  const supported =
    typeof navigator.mediaDevices?.getUserMedia === 'function' &&
    typeof (window.AudioContext || (window as any).webkitAudioContext) ===
      'function';

  const refreshDevices = useCallback(async () => {
    try {
      const available = await waitForAudioInput(
        navigator.mediaDevices.enumerateDevices(),
        undefined,
        'Браузер не предоставил список аудиоустройств.',
        5000,
      );
      if (mounted.current) {
        setDevices(available.filter(device => device.kind === 'audioinput'));
        setOutputs(available.filter(device => device.kind === 'audiooutput'));
        setDevicesReady(true);
      }
      return available;
    } catch {
      // The current track can still capture if enumeration is unavailable.
      return [];
    }
  }, []);

  const analyse = useCallback(
    async (take: GuitarTake) => {
      analysisRequest.current?.abort();
      if (monitoringRef.current) {
        pendingAnalysis.current = take;
        setProcessing(false);
        setNotice(
          'Аудио записано. Распознавание начнётся после выключения живого звука.',
        );
        return;
      }
      pendingAnalysis.current = undefined;
      const request = new AbortController();
      analysisRequest.current = request;
      setProcessing(true);
      setProgress(0);
      setError('');
      setNotice('');
      try {
        const notes = await transcribeGuitar(take, setProgress, request.signal);
        if (request.signal.aborted || !mounted.current) return;
        if (selectNotes(store.getState()).recordingVersion !== take.version) {
          setNotice(
            'Начата новая запись. Предыдущий фрагмент доступен как WAV.',
          );
          return;
        }
        store.dispatch(
          notesActions.addGuitarRecording({
            version: take.version,
            startedAt: take.startedAt,
            notes,
          }),
        );
        setNotice(
          notes.length
            ? `Распознано нот: ${notes.length}. Запись доступна в песочнице и Play Along.`
            : 'Ноты не найдены. Проверьте уровень и канал входа. Аудиозапись можно скачать.',
        );
      } catch {
        if (!request.signal.aborted && mounted.current)
          setError(
            'Не удалось распознать запись. Повторите попытку или скачайте аудио.',
          );
      } finally {
        if (!request.signal.aborted && mounted.current) setProcessing(false);
      }
    },
    [store],
  );

  const muteMonitoring = useCallback(() => {
    monitoringRef.current = false;
    monitoringRequest.current++;
    timbreMonitor.current?.dispose();
    timbreMonitor.current = undefined;
    // setMonitoring(undefined) mutes synchronously, before its promise settles.
    void capture.current?.setMonitoring().catch(() => {});
    setMonitoring(false);
    setOutputLevel({ rms: 0, peak: 0 });
    const pending = pendingAnalysis.current;
    if (pending && !selectSettings(store.getState()).isRecording)
      void analyse(pending);
  }, [analyse, store]);

  const stopMonitoring = useCallback(() => {
    saveAudioRouting({ monitoringEnabled: false });
    muteMonitoring();
  }, [muteMonitoring]);

  const startMonitoring = async () => {
    const input = capture.current;
    if (!input || monitoringRef.current || document.hidden) return;
    saveAudioRouting({ monitoringEnabled: true });
    analysisRequest.current?.abort();
    if (processing && lastTake.current)
      pendingAnalysis.current = lastTake.current;
    setProcessing(false);
    monitoringRef.current = true;
    const request = ++monitoringRequest.current;
    setError('');
    try {
      const instrument = inputSoundRef.current === 'instrument';
      let session: ReturnType<typeof createTimbreMonitor> | undefined;
      if (instrument) {
        // Keep the original guitar silent, including the input effects' tails.
        void input.setMonitoring();
        const currentTimbre = selectSettings(store.getState()).timbre;
        session = createTimbreMonitor(
          input,
          currentTimbre,
          selectEffects(store.getState()).instruments[currentTimbre] ??
            defaultEffects(currentTimbre),
          inputPolyphonicRef.current,
          cause => {
            if (mounted.current && timbreMonitor.current === session) {
              muteMonitoring();
              setError(cause.message);
            }
          },
        );
        timbreMonitor.current = session;
      }
      await waitForAudioInput(
        session
          ? Promise.all([
              session.ready,
              input.audioContext.state === 'suspended'
                ? input.audioContext.resume()
                : Promise.resolve(),
            ]).then(() => {})
          : input.setMonitoring(effectsRef.current),
        connectionRequest.current?.signal,
        'Браузер не запустил живой звук.',
      );
      if (
        !mounted.current ||
        !monitoringRef.current ||
        request !== monitoringRequest.current ||
        capture.current !== input ||
        (session && timbreMonitor.current !== session)
      ) {
        session?.dispose();
        if (!session && request === monitoringRequest.current)
          void input.setMonitoring();
        return;
      }
      setMonitoring(true);
      setLatency(input.latency());
    } catch {
      if (
        mounted.current &&
        capture.current === input &&
        request === monitoringRequest.current
      ) {
        muteMonitoring();
        setError(
          'Не удалось включить живой звук. Проверьте аудиовыход и повторите попытку.',
        );
      }
    }
  };

  const restartMonitoring = useRef(startMonitoring);
  restartMonitoring.current = startMonitoring;
  useEffect(() => {
    if (inputSoundRef.current === 'instrument' && monitoringRef.current) {
      muteMonitoring();
      void restartMonitoring.current();
    }
  }, [timbre, muteMonitoring]);

  useEffect(() => {
    timbreMonitor.current?.updateEffects(
      instrumentEffects ?? defaultEffects(timbre),
    );
  }, [instrumentEffects, timbre]);

  const changeInputSound = (
    sound: typeof inputSound,
    polyphonic = inputPolyphonicRef.current,
  ) => {
    const resume = monitoringRef.current;
    muteMonitoring();
    inputSoundRef.current = sound;
    inputPolyphonicRef.current = polyphonic;
    setInputSound(sound);
    setInputPolyphonic(polyphonic);
    saveAudioRouting({ inputSound: sound, inputPolyphonic: polyphonic });
    if (resume) void startMonitoring();
  };

  const updateLiveEffects = (value: InstrumentEffects) => {
    const settings = normalizeEffects(LIVE_INPUT_EFFECTS_KEY, value);
    effectsRef.current = settings;
    if (monitoringRef.current && inputSoundRef.current === 'effects')
      void capture.current?.setMonitoring(settings).catch(muteMonitoring);
    store.dispatch(
      effectsActions.setInstrument({
        timbre: LIVE_INPUT_EFFECTS_KEY,
        settings,
      }),
    );
  };

  const finish = useCallback(
    async (closeInput = false) => {
      const active = taking.current;
      if (!active) {
        if (closeInput && flushing.current) flushing.current.close = true;
        return;
      }
      taking.current = undefined;
      const live = realtime.current;
      realtime.current = undefined;
      const drain = { input: active, close: closeInput, recognition: live };
      flushing.current = drain;
      setProcessing(true);
      setProgress(0);
      try {
        const take = await active.stopTake();
        if (drain.close) active.dispose();
        if (take && mounted.current) {
          lastTake.current = take;
          setHasTake(true);
          setLastTakeIsLive(!!live);
        }
        let recognitionFailed = false;
        if (live) {
          try {
            await live.finish();
          } catch (cause) {
            recognitionFailed = true;
            if (mounted.current)
              setError(
                cause instanceof Error
                  ? cause.message
                  : 'Не удалось завершить распознавание. Исходное аудио доступно как WAV.',
              );
          } finally {
            live.dispose();
          }
        }
        if (flushing.current === drain) flushing.current = undefined;
        if (!mounted.current) return;
        setDrainRevision(revision => revision + 1);
        if (!take) {
          setProcessing(false);
          return;
        }
        if (live) {
          setProcessing(false);
          if (
            !recognitionFailed &&
            selectNotes(store.getState()).recordingVersion === take.version
          )
            setNotice(
              live.noteCount
                ? `Записано нот в реальном времени: ${live.noteCount}. Запись доступна в песочнице и Play Along.`
                : 'Ноты не найдены. Проверьте уровень и канал входа. Исходное аудио можно скачать как WAV.',
            );
        } else await analyse(take);
      } catch {
        live?.dispose();
        if (drain.close) active.dispose();
        if (flushing.current === drain) flushing.current = undefined;
        if (mounted.current) {
          setProcessing(false);
          setError('Не удалось завершить захват аудио. Повторите запись.');
        }
      }
    },
    [analyse, store],
  );

  const stopRecording = useCallback(() => {
    if (selectSettings(store.getState()).isRecording) {
      batch(() => {
        store.dispatch(notesActions.finishRecording());
        store.dispatch(settingsActions.toggleRecording());
      });
    }
  }, [store]);

  const releaseInput = useCallback(async () => {
    muteMonitoring();
    stopRecording();
    const active = capture.current;
    capture.current = undefined;
    setConnected(false);
    setConnecting(false);
    setConnectionStatus('');
    setLevel({ rms: 0, peak: 0 });
    setLatency(undefined);
    // Drain the last partial PCM block before closing the context.
    const wasRecording = !!taking.current || !!flushing.current;
    const finishing = finish(true);
    if (!wasRecording) {
      active?.dispose();
      connectionRequest.current?.abort();
    }
    await finishing;
  }, [finish, muteMonitoring, stopRecording]);

  const disconnect = useCallback(() => {
    saveAudioRouting({ audioConnected: false });
    return releaseInput();
  }, [releaseInput]);

  const connect = async (id = deviceId) => {
    if (!supported || connecting || isRecording) return;
    const shouldMonitor = loadAudioRouting().monitoringEnabled !== false;
    saveAudioRouting({ audioConnected: true });
    muteMonitoring();
    connectionRequest.current?.abort();
    capture.current?.dispose();
    capture.current = undefined;
    const request = new AbortController();
    connectionRequest.current = request;
    setConnecting(true);
    setConnectionStatus('Ожидаем доступ к микрофону…');
    setConnected(false);
    setError('');
    try {
      const input = await openGuitarCapture(
        id,
        request.signal,
        () => {
          stopRecording();
          setError('Аудиоустройство отключено. Запись остановлена.');
          void releaseInput();
        },
        message => {
          if (!request.signal.aborted && mounted.current)
            setConnectionStatus(message);
        },
      );
      if (request.signal.aborted || !mounted.current) {
        input.dispose();
        return;
      }
      capture.current = input;
      input.setNoiseGate(noiseGateRef.current);
      const preferences = loadAudioRouting();
      const restoredChannel =
        input.deviceId === preferences.inputDeviceId
          ? Math.min(preferences.inputChannel, input.channels - 1)
          : 0;
      setDeviceId(input.deviceId);
      setChannel(restoredChannel);
      if (restoredChannel) input.setChannel(restoredChannel);
      saveAudioRouting({
        inputDeviceId: input.deviceId,
        inputChannel: restoredChannel,
      });
      setChannels(input.channels);
      setOutputDeviceId('');
      setCanSelectOutput(input.canSelectOutput);
      setLatency(input.latency());
      setConnectionStatus('Получаем список аудиоустройств…');
      const available = await refreshDevices();
      if (request.signal.aborted || !mounted.current) return;
      const selectedOutput = preferences.liveOutputDeviceId;
      const output =
        selectedOutput !== null
          ? selectedOutput
          : builtInOutput(available)?.deviceId;
      if (input.canSelectOutput && output !== undefined) {
        setConnectionStatus('Выбираем аудиовыход…');
        try {
          await waitForAudioInput(
            input.setOutputDevice(output),
            request.signal,
            'Браузер не завершил выбор аудиовыхода.',
          );
        } catch {
          if (!request.signal.aborted && mounted.current) {
            setConnected(true);
            setError(
              selectedOutput !== null
                ? 'Сохранённый аудиовыход недоступен. Выберите аудиовыход и включите живой звук.'
                : 'Не удалось выбрать встроенные динамики. Выберите аудиовыход и включите живой звук.',
            );
          }
          return;
        }
        if (request.signal.aborted || !mounted.current) return;
        setOutputDeviceId(output);
        saveAudioRouting({ liveOutputDeviceId: output });
        setLatency(input.latency());
      }
      setConnected(true);
      if (shouldMonitor) {
        setConnectionStatus('Включаем живой звук…');
        await startMonitoring();
      }
    } catch (cause) {
      if (!request.signal.aborted && mounted.current)
        setError(errorMessage(cause));
    } finally {
      if (!request.signal.aborted && mounted.current) {
        setConnecting(false);
        setConnectionStatus('');
      }
    }
  };

  const restoreConnection = useRef(connect);
  restoreConnection.current = connect;
  useEffect(() => {
    let active = true;
    // Defer until mount effects finish, including React StrictMode's cleanup.
    void Promise.resolve().then(() => {
      if (active && supported && savedRouting.audioConnected)
        void restoreConnection.current(savedRouting.inputDeviceId);
    });
    return () => {
      active = false;
    };
  }, [savedRouting.audioConnected, savedRouting.inputDeviceId, supported]);

  useEffect(() => {
    if (monitoringRef.current && inputSoundRef.current === 'effects')
      void capture.current?.setMonitoring(liveEffects).catch(muteMonitoring);
  }, [liveEffects, muteMonitoring]);

  useEffect(() => {
    if (
      isRecording &&
      connected &&
      capture.current &&
      !taking.current &&
      !flushing.current
    ) {
      analysisRequest.current?.abort();
      pendingAnalysis.current = undefined;
      setProcessing(false);
      setNotice('');
      setError('');
      taking.current = capture.current;
      const version = selectNotes(store.getState()).recordingVersion;
      if (recordingMode !== 'polyphonic') {
        const live = createLiveTranscription(
          frame => {
            if (mounted.current)
              store.dispatch(
                notesActions.streamGuitarNotes({
                  version,
                  events: frame.events,
                  soundingNotes: frame.soundingNotes,
                }),
              );
          },
          cause => {
            if (
              mounted.current &&
              selectNotes(store.getState()).recordingVersion === version
            ) {
              store.dispatch(
                notesActions.streamGuitarNotes({
                  version,
                  events: [],
                  soundingNotes: [],
                }),
              );
              setError(cause.message);
            }
          },
          recordingMode === 'live-mono',
        );
        realtime.current = live;
        capture.current.startTake(version, live.push);
      } else capture.current.startTake(version);
    } else if (!isRecording) void finish();
  }, [connected, drainRevision, finish, isRecording, recordingMode, store]);

  useEffect(() => {
    if (!connected) return;
    const timer = setInterval(() => {
      if (capture.current) {
        setLevel(capture.current.level());
        setOutputLevel(
          timbreMonitor.current?.level() ?? capture.current.outputLevel(),
        );
      }
    }, 100);
    return () => clearInterval(timer);
  }, [connected]);

  useEffect(() => {
    mounted.current = true;
    const media = navigator.mediaDevices;
    void refreshDevices();
    media?.addEventListener?.('devicechange', refreshDevices);
    return () => {
      mounted.current = false;
      media?.removeEventListener?.('devicechange', refreshDevices);
      connectionRequest.current?.abort();
      analysisRequest.current?.abort();
      monitoringRef.current = false;
      timbreMonitor.current?.dispose();
      timbreMonitor.current = undefined;
      capture.current?.dispose();
      realtime.current?.dispose();
      flushing.current?.recognition?.dispose();
      flushing.current?.input.dispose();
      capture.current = undefined;
    };
  }, [refreshDevices]);

  const toggleRecording = () => {
    if (isRecording) {
      stopRecording();
      return;
    }
    if (!connected || processing) return;
    const { isRecording: _, ...settings } = selectSettings(store.getState());
    batch(() => {
      store.dispatch(notesActions.startRecording({ ...settings, title: '' }));
      store.dispatch(settingsActions.toggleRecording());
    });
  };

  return {
    inputSound,
    inputPolyphonic,
    setInputSound: changeInputSound,
    setInputPolyphonic: (polyphonic: boolean) =>
      changeInputSound(inputSoundRef.current, polyphonic),
    recordingMode,
    setRecordingMode: (mode: RecordingMode) => {
      if (!selectSettings(store.getState()).isRecording && !flushing.current)
        setRecordingMode(mode);
    },
    canRetry: !lastTakeIsLive,
    noiseGate,
    updateNoiseGate: (value: NoiseGateSettings) => {
      const next = normalizeNoiseGate(value);
      noiseGateRef.current = next;
      capture.current?.setNoiseGate(next);
      setNoiseGate(next);
      saveNoiseGate(next);
    },
    supported,
    monitoring,
    startMonitoring,
    stopMonitoring,
    liveEffects,
    updateLiveEffects,
    outputLevel,
    latency,
    connected,
    connecting,
    connectionStatus,
    devices,
    devicesReady,
    requestingDevices,
    requestDevices: async () => {
      if (!supported || requestingDevices) return;
      setRequestingDevices(true);
      setError('');
      let stream: MediaStream | undefined;
      let expired = false;
      try {
        if (!capture.current)
          stream = await waitForAudioInput(
            navigator.mediaDevices.getUserMedia({ audio: true }).then(value => {
              if (expired || !mounted.current) {
                value.getTracks().forEach(track => track.stop());
                throw new DOMException('Request cancelled', 'AbortError');
              }
              return value;
            }),
            undefined,
            microphoneTimeoutMessage,
            30000,
          );
        await refreshDevices();
      } catch (cause) {
        if (mounted.current) setError(errorMessage(cause));
      } finally {
        expired = true;
        stream?.getTracks().forEach(track => track.stop());
        if (mounted.current) setRequestingDevices(false);
      }
    },
    outputs,
    outputDeviceId,
    canSelectOutput,
    selectOutput: async (id: string) => {
      stopMonitoring();
      const input = capture.current;
      if (!input) return;
      try {
        await input.setOutputDevice(id);
        if (capture.current !== input || !mounted.current) return;
        setOutputDeviceId(id);
        saveAudioRouting({ liveOutputDeviceId: id });
        setLatency(input.latency());
      } catch {
        if (mounted.current)
          setError(
            'Не удалось выбрать аудиовыход. Проверьте разрешения или выберите выход в настройках системы.',
          );
      }
    },
    deviceId,
    channel,
    channels,
    level,
    isRecording: isRecording && connected,
    processing,
    progress,
    error,
    notice,
    hasTake,
    exporting,
    exportError,
    connect,
    disconnect,
    toggleRecording,
    selectDevice: (id: string) => {
      setDeviceId(id);
      void connect(id);
    },
    selectChannel: (value: number) => {
      if (isRecording) return;
      stopMonitoring();
      capture.current?.setChannel(value);
      setChannel(value);
      saveAudioRouting({ inputChannel: value });
    },
    retry: () => {
      if (lastTake.current && !processing) void analyse(lastTake.current);
    },
    download: () => {
      if (lastTake.current) downloadGuitarTake(lastTake.current);
    },
    downloadWithEffects: async () => {
      const take = lastTake.current;
      if (!take || exportingRef.current) return;
      const settings = normalizeEffects(
        LIVE_INPUT_EFFECTS_KEY,
        effectsRef.current,
      );
      const gate = { ...noiseGateRef.current };
      exportingRef.current = true;
      setExporting(true);
      setExportError('');
      try {
        const [{ renderGuitarAudio }, { encodeWav }] = await Promise.all([
          import('./export'),
          import('app/services/MelodyExportService/audio'),
        ]);
        const audio = await renderGuitarAudio(take, settings, gate);
        if (mounted.current)
          downloadGuitarWav(encodeWav(audio), 'qwertophone-guitar-effects.wav');
      } catch (cause) {
        if (mounted.current)
          setExportError(
            cause instanceof Error
              ? cause.message
              : 'Не удалось обработать запись. Повторите скачивание или выберите чистый WAV.',
          );
      } finally {
        exportingRef.current = false;
        if (mounted.current) setExporting(false);
      }
    },
  };
};
