import {
  IMPORT_TIMEOUT_MS,
  ImportResponse,
  ImportedSong,
  MelodyImportError,
} from './types';

export const readInWorker = (
  worker: Worker,
  name: string,
  data: ArrayBuffer,
  signal?: AbortSignal,
): Promise<ImportedSong> =>
  new Promise((resolve, reject) => {
    const dispose = () => {
      clearTimeout(timer);
      worker.terminate();
      signal?.removeEventListener('abort', abort);
    };
    const fail = (cause: Error) => {
      dispose();
      reject(cause);
    };
    const abort = () => fail(new DOMException('Импорт отменён', 'AbortError'));
    const timer = setTimeout(
      () =>
        fail(
          new MelodyImportError(
            'Обработка файла заняла слишком много времени. Попробуйте файл с меньшим количеством партий.',
          ),
        ),
      IMPORT_TIMEOUT_MS,
    );
    worker.onmessage = ({ data: response }: MessageEvent<ImportResponse>) => {
      dispose();
      if ('error' in response) reject(new MelodyImportError(response.error));
      else resolve(response.song);
    };
    worker.onerror = event => {
      event.preventDefault();
      fail(
        new MelodyImportError(
          'Не удалось запустить импорт. Обновите страницу и повторите выбор файла.',
        ),
      );
    };
    worker.onmessageerror = () =>
      fail(
        new MelodyImportError(
          'Не удалось получить результат импорта. Попробуйте ещё раз.',
        ),
      );
    if (signal?.aborted) {
      abort();
      return;
    }
    signal?.addEventListener('abort', abort, { once: true });
    try {
      worker.postMessage({ name, data }, [data]);
    } catch {
      fail(
        new MelodyImportError(
          'Не удалось передать файл для обработки. Попробуйте ещё раз.',
        ),
      );
    }
  });
