import { Note, Octave, getNote, pitchNote } from 'app/services/NotesService';
import type { SettingsState } from 'app/services/SettingsService/slice/types';

import { KeyCode } from './types';

export const getKeyboardNote = (
  key: KeyCode,
  {
    applicature,
    scaleNotes,
    octave,
    pitch,
  }: Pick<SettingsState, 'applicature' | 'scaleNotes' | 'octave' | 'pitch'>,
): Note | null => {
  const index = applicature.indexOf(key);
  if (index === -1 || !scaleNotes.length) return null;
  return pitchNote(
    getNote(
      scaleNotes[index % scaleNotes.length],
      (octave + Math.floor(index / scaleNotes.length)) as Octave,
    ),
    pitch,
  );
};
